6	# KMP Dependency Injection
7	
8	Cross-platform dependency injection with Koin.
9	
10	## Koin Multiplatform Setup
11	
12	### Dependencies
13	
14	```kotlin
15	// build.gradle.kts (shared module)
16	sourceSets {
17	    val commonMain by getting {
18	        dependencies {
19	            implementation("io.insert-koin:koin-core:${koinVersion}")
20	            implementation("io.insert-koin:koin-test:${koinVersion}")
21	        }
22	    }
23	    val androidMain by getting {
24	        dependencies {
25	            implementation("io.insert-koin:koin-android:${koinVersion}")
26	        }
27	    }
28	}
29	```
30	
31	### Module Definition
32	
33	```kotlin
34	// commonMain/kotlin/di/AppModule.kt
35	val sharedModule = module {
36	    // ViewModels (Android) / ScreenModels (multiplatform)
37	    factory { HomeViewModel(get(), get()) }
38	    factory { DetailViewModel(get()) }
39	
40	    // Use Cases
41	    factory { GetUsersUseCase(get()) }
42	    factory { GetUserDetailUseCase(get()) }
43	
44	    // Repositories
45	    single<UserRepository> { UserRepositoryImpl(get(), get()) }
46	
47	    // Data Sources
48	    single { UserApi(get()) }
49	    single { createDatabase(get()) }
50	}
51	```
52	
53	### Platform Modules
54	
55	```kotlin
56	// androidMain/kotlin/di/PlatformModule.kt
57	val androidPlatformModule = module {
58	    includes(sharedModule)
59	
60	    // Android-specific dependencies
61	    single { android.content.Context() }
62	    single { PlatformConnectivityMonitor(get()) }
63	    single { PlatformFileService(get()) }
64	}
65	
66	// iosMain/kotlin/di/PlatformModule.kt
67	val iosPlatformModule = module {
68	    includes(sharedModule)
69	
70	    // iOS-specific dependencies
71	    single { PlatformConnectivityMonitor() }
72	    single { PlatformFileService() }
73	}
74	```
75	
76	## Koin Start
77	
78	### Android
79	
80	```kotlin
81	// androidMain/kotlin/MyApp.kt
82	class MyApp : Application() {
83	    override fun onCreate() {
84	        super.onCreate()
85	        startKoin {
86	            androidContext(this@MyApp)
87	            modules(androidPlatformModule)
88	        }
89	    }
90	}
91	```
92	
93	### iOS
94	
95	```kotlin
96	// iosMain/kotlin/di/KoinInit.kt
97	fun initKoin() {
98	    startKoin {
99	        modules(iosPlatformModule)
100	    }
101	}
102	
103	// Called from Swift
104	// KotlinKMMSharedKt.doInitKoin()
105	```
106	
107	### Compose Multiplatform
108	
109	```kotlin
110	// commonMain/kotlin/Main.kt
111	fun main() {
112	    startKoin {
113	        modules(sharedModule)
114	    }
115	
116	    App()
117	}
118	```
119	
120	## ViewModel Injection
121	
122	### Android (ViewModel)
123	
124	```kotlin
125	// androidMain/kotlin/ui/HomeScreen.kt
126	@Composable
127	fun HomeScreen(
128	    viewModel: HomeViewModel = koinViewModel()
129	) {
130	    val state by viewModel.state.collectAsStateWithLifecycle()
131	    HomeContent(state)
132	}
133	```
134	
135	### iOS (ScreenModel)
136	
137	```kotlin
138	// commonMain/kotlin/ui/HomeScreen.kt
139	@Composable
140	fun HomeScreen() {
141	    val model = getScreenModel<HomeScreenModel>()
142	    val state by model.state.collectAsState()
143	
144	    HomeContent(state)
145	}
146	```
147	
148	## Repository Pattern
149	
150	### Factory vs Single
151	
152	```kotlin
153	// ✅ factory - creates new instance each time
154	factory { HomeViewModel(get(), get()) }
155	
156	// ✅ single - shared instance
157	single<UserRepository> { UserRepositoryImpl(get(), get()) }
158	
159	// ✅ scoped - tied to component lifetime
160	scoped(HomeScope.homeScope) { HomeData(get()) }
161	```
162	
163	## Named Dependencies
164	
165	```kotlin
166	// ✅ Named dependencies
167	module {
168	    single(named("default")) { DefaultLogger() }
169	    single(named("analytics")) { AnalyticsLogger() }
170	
171	    factory { MyRepository(logger = get(named("default"))) }
172	}
173	```
174	
175	## Manual DI (Alternative)
176	
177	### Simple Service Locator
178	
179	```kotlin
180	// commonMain/kotlin/di/ServiceLocator.kt
181	object ServiceLocator {
182	    private val services = mutableMapOf<String, Any>()
183	
184	    fun <T> get(key: String): T {
185	        return services[key] as T
186	    }
187	
188	    fun register(key: String, service: Any) {
189	        services[key] = service
190	    }
191	
192	    fun init() {
193	        register("repository", UserRepositoryImpl())
194	        register("api", UserApi())
195	    }
196	}
197	```
198	
199	### Pure Kotlin DI
200	
201	```kotlin
202	// commonMain/kotlin/di/AppContainer.kt
203	class AppContainer(
204	    private val platformService: PlatformService
205	) {
206	    val api: UserApi = UserApi()
207	    val database: AppDatabase = createDatabase()
208	
209	    val userRepository: UserRepository by lazy {
210	        UserRepositoryImpl(api, database)
211	    }
212	
213	    val homeViewModel: HomeViewModel by lazy {
214	        HomeViewModel(userRepository, platformService)
215	    }
216	}
217	```
218	
219	## Testing with DI
220	
221	```kotlin
222	// commonTest/kotlin/di/TestModule.kt
223	val testModule = module {
224	    single<MockUserService> { MockUserService() }
225	    single<UserService>(override = true) { get<MockUserService>() }
226	}
227	
228	// In tests
229	@BeforeTest
230	fun setup() {
231	    startKoin { modules(testModule) }
232	}
233	
234	@AfterTest
235	fun tearDown() {
236	    stopKoin()
237	}
238	```
239	
240	---
241	
242	**Remember**: DI simplifies testing. Use it to inject mocks and fakes easily.
